          "status": "supported"
        },
        "3": {
          "evidence": "The inscription '12%' is printed directly above the bar labeled 'Safari'.",
          "status": "supported"
        },
        "4": {
          "evidence": "The inscription '6%' is printed directly above the bar labeled 'Firefox'.",
          "status": "supported"
        }
      },
      "B": {
        "reading_checked": "If the percentage inscriptions above product bars are the authoritative browser usage-share values, and primary compatibility targeting is assigned to the selectable browser with the greatest shown usage share, select that browser.",
        "evidence": "The percentage inscriptions are clearly printed above each bar and correspond to the bar below them. The values are 73% for Chrome, 12% for Safari, 6% for Firefox. The selectable browsers are Chrome, Safari, and Firefox. Chrome has the highest value (73%), which is greater than Safari (12%) and Firefox (6%). The condition that the percentages are authoritative and that the target is the browser with the greatest shown share is satisfied by the data.",
        "status": "supported"
      }
    }
